export type OpmRpcMethodName = keyof OpmRpcMethods

/** What `Call` accepts for `T`: members may be omitted, enums sent by name. */
export type OpmInput<T> = T extends number
  ? number extends T
    ? T
    : T | string
  : T extends string | boolean | null | undefined
    ? T
    : T extends readonly (infer E)[]
      ? OpmInput<E>[]
      : { [K in keyof T]?: OpmInput<T[K]> }

export type OpmRpcArgs<M extends OpmRpcMethodName> = {
  [I in keyof OpmRpcMethods[M]["args"]]: OpmInput<OpmRpcMethods[M]["args"][I]>
}
export type OpmRpcResult<M extends OpmRpcMethodName> = OpmRpcMethods[M]["result"]
export type OpmBroadcast = SignalRRpcBroadcastMessage

/** Events relayed to topic subscribers, also sent as an `OpmBroadcast` of kind `existing:<name>`. */
export interface OpmEvents {
  OnRobotEntityChanged: [robotId: string | null, robot: Robot | null]
  OnStockSkusChanged: [e: OnStockSkusChangedEvent | null]
}

